using System.Collections.Generic;
using System.Globalization;
using System.Linq;

namespace Astrea;

public static class LanguagesIndexes
{
	public const int AUTO_INDEX = -1;

	public const int ENGLISH_INDEX = 0;

	public const int PT_BR_INDEX = 1;

	public const int CHINESE_SIMPLIFIED_INDEX = 2;

	public const int CHINESE_TRADITIONAL_INDEX = 3;

	public const int FRENCH_INDEX = 4;

	public const int GERMAN_INDEX = 5;

	public const int JAPANESE_INDEX = 6;

	public const int KOREAN_INDEX = 7;

	public const int RUSSIAN_INDEX = 8;

	public const int SPANISH_INDEX = 9;

	private static Dictionary<int, bool> languageActive = new Dictionary<int, bool>
	{
		{ 1, true },
		{ 2, true },
		{ 3, true },
		{ 4, true },
		{ 5, true },
		{ 6, true },
		{ 7, true },
		{ 8, true },
		{ 9, true }
	};

	public static int LanguageIndex = -1;

	public static int CurrentLanguageIndex
	{
		get
		{
			int num = LanguageIndex;
			if (num <= -1)
			{
				num = GetSystemLanguage();
			}
			if (!GetLanguageActive(num))
			{
				num = 0;
			}
			return num;
		}
	}

	private static int GetSystemLanguage()
	{
		CultureInfo currentCulture = CultureInfo.CurrentCulture;
		if (currentCulture.ThreeLetterISOLanguageName == "por")
		{
			if (currentCulture.Name == "pt-BR")
			{
				return 1;
			}
			return 0;
		}
		if (currentCulture.ThreeLetterISOLanguageName == "eng")
		{
			return 0;
		}
		if (currentCulture.ThreeLetterISOLanguageName == "fra")
		{
			return 4;
		}
		if (currentCulture.ThreeLetterISOLanguageName == "deu")
		{
			return 5;
		}
		if (currentCulture.ThreeLetterISOLanguageName == "spa")
		{
			return 9;
		}
		if (currentCulture.ThreeLetterISOLanguageName == "jpn")
		{
			return 6;
		}
		if (currentCulture.ThreeLetterISOLanguageName == "rus")
		{
			return 8;
		}
		if (currentCulture.ThreeLetterISOLanguageName == "kor")
		{
			return 7;
		}
		if (currentCulture.ThreeLetterISOLanguageName == "zho")
		{
			if (currentCulture.Name == "zh-CHS" || currentCulture.Name == "zh-CN" || currentCulture.Name == "zh-SG")
			{
				return 2;
			}
			return 3;
		}
		return 0;
	}

	public static void LoadLanguage(SaveSystem saveSystem)
	{
		if (saveSystem.HasLanguageSaveKey())
		{
			LanguageIndex = saveSystem.LoadLanguage();
		}
		else
		{
			LanguageIndex = -1;
		}
	}

	public static bool GetLanguageActive(int languageIndex)
	{
		if (languageActive.ContainsKey(languageIndex) && !languageActive[languageIndex])
		{
			return false;
		}
		return true;
	}

	public static bool IsIgnoreLineBreakOnEffectFeedback()
	{
		if (CurrentLanguageIndex != 2 && CurrentLanguageIndex != 3 && CurrentLanguageIndex != 6)
		{
			return CurrentLanguageIndex == 7;
		}
		return true;
	}

	public static bool IsCurrentLanguageSimplifiedChinese()
	{
		return CurrentLanguageIndex == 2;
	}

	public static bool IsCurrentLanguageTraditionalChinese()
	{
		return CurrentLanguageIndex == 3;
	}

	public static bool IsCurrentLanguageKorean()
	{
		return CurrentLanguageIndex == 7;
	}

	public static bool IsCurrentLanguageJapanese()
	{
		return CurrentLanguageIndex == 6;
	}

	public static bool IsCurrentLanguageRussian()
	{
		return CurrentLanguageIndex == 8;
	}

	public static bool IsCurrentLanguageFrench()
	{
		return CurrentLanguageIndex == 4;
	}

	public static bool IsCurrentLanguageGerman()
	{
		return CurrentLanguageIndex == 5;
	}

	public static bool IsCurrentLanguageSpanish()
	{
		return CurrentLanguageIndex == 9;
	}

	public static bool IsCurrentLanguageEnglish()
	{
		return CurrentLanguageIndex == 0;
	}

	public static bool IsCurrentLanguagePortuguese()
	{
		return CurrentLanguageIndex == 1;
	}

	public static bool IsCurrentLanguageLatinLanguage()
	{
		if (CurrentLanguageIndex != 1)
		{
			return CurrentLanguageIndex == 9;
		}
		return true;
	}

	public static bool IsIgnoreSpacingOnSomeUI()
	{
		if (CurrentLanguageIndex != 2 && CurrentLanguageIndex != 3)
		{
			return CurrentLanguageIndex == 6;
		}
		return true;
	}

	public static bool IsLanguageWithoutSpacing()
	{
		if (CurrentLanguageIndex != 2 && CurrentLanguageIndex != 3 && CurrentLanguageIndex != 6)
		{
			return CurrentLanguageIndex == 7;
		}
		return true;
	}

	public static bool IsLanguageWithSpaceBeforePercentage()
	{
		if (CurrentLanguageIndex != 4)
		{
			return CurrentLanguageIndex == 9;
		}
		return true;
	}

	public static bool IsCurrentLanguageKanji()
	{
		if (CurrentLanguageIndex != 2 && CurrentLanguageIndex != 3 && CurrentLanguageIndex != 6)
		{
			return CurrentLanguageIndex == 7;
		}
		return true;
	}

	public static string RemoveLastIfDotOrComma(this string text)
	{
		if (text.Last() == ',' || text.Last() == '.' || text.Last() == '、' || text.Last() == '。' || text.Last() == '，')
		{
			return text.RemoveLast();
		}
		return text;
	}

	public static string RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese(this string text)
	{
		if (!IsCurrentLanguageJapanese() && !IsCurrentLanguageKorean() && !IsCurrentLanguageTraditionalChinese())
		{
			return text.RemoveLast();
		}
		return text;
	}

	public static string RemoveLastIfDotOrCommaAndIfNotJapaneseNorKoreanNorTraditionalChinese(this string text)
	{
		if (!IsCurrentLanguageJapanese() && !IsCurrentLanguageKorean() && !IsCurrentLanguageTraditionalChinese())
		{
			return text.RemoveLastIfDotOrComma();
		}
		return text;
	}

	public static string RemoveLastIfNotJapaneseNorKorean(this string text)
	{
		if (!IsCurrentLanguageJapanese() && !IsCurrentLanguageKorean())
		{
			return text.RemoveLast();
		}
		return text;
	}

	public static string AddDotIfJapaneseOrKoreanOrTraditionalChinese(this string text)
	{
		if (IsCurrentLanguageJapanese())
		{
			return text + "。";
		}
		if (IsCurrentLanguageTraditionalChinese())
		{
			return text + "。";
		}
		if (IsCurrentLanguageKorean())
		{
			return text + ".";
		}
		return text;
	}
}
